import { FetchParams, Middleware, RequestContext } from "../lib";
export class DataCloudMiddleware implements Middleware {
    pre = (context: RequestContext): Promise<FetchParams | void> => {
        return new Promise<void>((resolve,reject) => {
            let newHeaders = new Headers(context.init.headers);
            newHeaders.set('content-type','application/x-www-form-urlencoded');
            context.init.headers = newHeaders;

            if (context.init.body === null) reject("Body can't be null");
            context.init.body =  "event=" + btoa(context.init.body!.toString());
            resolve();
        })

    }
}